{
  "story": "RLHF aligns language models using human preferences. First, the model generates responses. Next, human raters rank them. Finally, a reward model scores outputs and guides the policy.",
  "aha": {
    "stateId": "step-3",
    "observation": "Human preference signals train a reward model that directly guides policy updates."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "RLHF Step",
      "options": [
        "step-1",
        "step-2",
        "step-3"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Overview",
        "regions": [
          {
            "id": "reg-model",
            "label": "Base Model"
          },
          {
            "id": "reg-human",
            "label": "Human Raters"
          },
          {
            "id": "reg-reward",
            "label": "Reward Model"
          }
        ],
        "states": [
          {
            "id": "step-1",
            "label": "Generation",
            "short": "Generate",
            "sentence": "The base model generates multiple candidate responses for a single prompt.",
            "why": "Establishes a batch of diverse outputs for comparison.",
            "calloutRegion": "reg-model",
            "readouts": [
              {
                "id": "r1",
                "label": "Candidates",
                "value": "4 outputs"
              }
            ]
          },
          {
            "id": "step-2",
            "label": "Preference",
            "short": "Rank",
            "sentence": "Human raters rank the generated responses from best to worst.",
            "why": "Provides ground truth data reflecting human values.",
            "calloutRegion": "reg-human",
            "readouts": [
              {
                "id": "r2",
                "label": "Agreement",
                "value": "85%"
              }
            ]
          },
          {
            "id": "step-3",
            "label": "Optimization",
            "short": "Optimize",
            "sentence": "A reward model scores responses, updating the policy via reinforcement learning.",
            "why": "Aligns model behavior with human preferences.",
            "calloutRegion": "reg-reward",
            "readouts": [
              {
                "id": "r3",
                "label": "Reward",
                "value": "+2.4 score"
              }
            ]
          }
        ]
      }
    ]
  }
}
